insert into public.programs (id, institution_id, name, country, degree, field, official_url, status, pathway_type, status_note, intake, deadline, min_gpa_rule, language_req, tuition, living_cost, duration_months, scholarship_info, sop_requirements, lor_count, cv_requirements, tests_required, research_considered, progression_guaranteed, progression_requirement, eligibility_note, conditional_admission, language_waiver, admissions_email, last_checked) values
  ('tum-msc-informatics', 'tum', 'MSc Informatics', 'DE', 'MSc', 'cs', 'https://www.cit.tum.de/en/cit/studies/degree-programs/master-informatics/', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"Summer or Winter semester","source_url":"https://www.cit.tum.de/en/cit/studies/degree-programs/master-informatics/","evidence_snippet":"Start of Degree Program: Summer or Winter semester Language of Instruction: English","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Same page lists lecture start ''Winter semester: October'' and ''Summer semester: April''. Target intake for current applicants: winter semester 2027/28."}'::jsonb, '{"value":"2027-05-31","source_url":"https://www.cit.tum.de/en/cit/studies/degree-programs/master-informatics/","evidence_snippet":"For the winter semester: February 1 – March 31: recommended application deadline for applicants who need a visa February 1 – May 31: compulsory application deadline","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Winter semester 2027/28 intake. Page gives dates without a year; 31 May is the next occurrence of the compulsory deadline (2027). Pakistani applicants need a visa, so TUM RECOMMENDS applying by 31 March 2027. Summer semester window: 1 October - 30 November. Apply via TUMonline; uni-assist VPD required for non-German bachelor''s.","basis":"inferred","note":"For the winter semester. Applications open 1 February. Applicants who need a visa are recommended to apply by 31 March."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":24,"source_url":"https://www.cit.tum.de/en/cit/studies/degree-programs/master-informatics/","evidence_snippet":"Standard Duration of Studies: 4 semesters Credits: 120 ECTS","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. 4 semesters = 24 months (standard duration)."}'::jsonb, '{"value":"TUM scholarship for international students: a one-time study grant of 500 to 1,800 euros per semester. Both academic performance and financial circumstances are considered in selection, and you can apply again each semester.","source_url":"https://www.tum.de/en/studies/fees/tuition","evidence_snippet":"TUM scholarship for international students TUM supports international students through scholarships. Both academic performance and financial circumstances are taken into account during the selection process. You can receive a one-time study grant of 500 to 1,800 euros per semester. Applications can be submitted again each semester.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. On TUM''s ''Tuition Fees for Students from Non-EU Countries'' page. The grant is per semester and much smaller than the tuition fee (6,000 EUR/semester now; 4,600 or 6,800 EUR from WS 2027/28). The page does not say when or by whom it can be applied for (appears to be for enrolled students); the Informatics programme page adds ''Many international students can have their fees waived or receive scholarships to finance them.''"}'::jsonb, '{"value":"Statement of reasons in English, no longer than two DIN-A4 pages.","source_url":"https://www.cit.tum.de/en/cit/studies/degree-programs/master-informatics/","evidence_snippet":"The statement of reasons, submitted along with the online application, should not be longer than two DIN-A4 pages and must be written in English.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Essay requirement on the same page: ''The scientific essay / paper, submitted along with the online application, should be approximately 1,000 words in length and must be written in English.'' Stage 2 may be a 90-minute written test."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"GRE (General) required for applicants with a degree from Pakistan. Minimum scores: Quantitative reasoning 164, Analytical writing 4.0 (Verbal reasoning is not taken into account). Lower scores are not accepted.","source_url":"https://www.cit.tum.de/en/cit/studies/degree-programs/master-informatics/","evidence_snippet":"Applicants with a Degree from Bangladesh, China, India, Iran or Pakistan have to submit a GRE (General) Test. We have defined required minimum scores, lower scores will not be accepted! The required scores are: Verbal reasoning: (will not be taken into account anymore) Quantitative reasoning: 164 Analytical writing: 4.0","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Applies to applicants whose B.Sc. is from Pakistan. Same page: ''Alternatively, students can submit a scorecard of the Indian GATE test (Computer Science...)''. GRE institution code 7806, department 5199."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('ethz-msc-cs', 'ethz', 'MSc Computer Science', 'CH', 'MSc', 'cs', 'https://ethz.ch/en/studies/master/degree-programmes/engineering-sciences/computer-science.html', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2026-11-30","source_url":"https://www.lehrbetrieb.ethz.ch/eApply/","evidence_snippet":"The application period for Master''s degree programmes lasts from 1 November 2026 00:00 to 30 November 2026 12:00 CET \"(noon)\". Late applications are not possible.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. For Master''s starting autumn semester 2027 (eApply portal). Closes at NOON CET on 30 Nov 2026 - only 6 days after this research date. ETH-wide Master''s window; per ETH CS brochure (PDF, not used) the April window is only for Swiss bachelor''s holders, so the November window is the one for Pakistani applicants. eApply URL redirects to a session login page; the text is in the raw HTML.","note":"Applications close at 12:00 noon CET on 30 November 2026. Late applications are not possible."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":null,"toefl_ibt":null,"waiver":null,"text":"English, Level C1; proof of proficiency required by the application deadline (see ETH Language requirements)."},"source_url":"https://ethz.ch/en/studies/master/application/master-informatik.html","evidence_snippet":"English, proof of proficiency required by the application deadline: Level C1, see Language requirements","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. No numeric IELTS/TOEFL minimum in the raw HTML (score list on https://ethz.ch/en/studies/master/application/language-requirements.html is not in the static text). Exemption on that page (human reviewer may add as waiver): ''Applicants who complete a Bachelor’s degree programme completely taught in English. The language of instruction must be officially confirmed by the university.'' Certificates (TOEFL, IELTS, CAE) must be no more than two years old."}'::jsonb, '{"value":{"amount":2190,"currency":"CHF","period":"semester"},"source_url":"https://ethz.ch/students/en/studies/financial/tuition-fees.html","evidence_snippet":"Threefold tuition fee: CHF 2190 / semester All students who do not fulfil the criteria for simple tuition fee will be assigned to the second group paying a threefold tuition fee.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Applies since autumn semester 2025 to students who are not Swiss/Liechtenstein citizens and were not resident in CH/LI when they obtained their university entrance qualification, i.e. typical Pakistani applicants (ETH checks the group during admission). Simple fee is CHF 730/semester. Tuition only; semester fees are extra. Section marked ''updated 19.11.2025''. CONFLICT: see the CHF 804 proposal from https://ethz.ch/en/studies/financial.html."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":24,"source_url":"https://ethz.ch/en/studies/master/degree-programmes/engineering-sciences/computer-science.html","evidence_snippet":"Credits | duration 120 ECTS | 2 years","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. 2 years = 24 months."}'::jsonb, '{"value":"Excellence Scholarship & Opportunity Programme (ESOP): scholarship, mentorship and a network of the ETH Foundation; it covers the full study and living costs during the Master''s. Apply in the application window 1 to 30 November 2026 (closes 11.59h MEZ/CET) for a start in autumn semester 2027 (HS27).","source_url":"https://ethz.ch/students/en/studies/financial/scholarships/excellencescholarship.html","evidence_snippet":"The Excellence Scholarship & Opportunity Programme (ESOP) supports students with a scholarship, mentorship and a network of the ETH Foundation. The scholarship covers the full study and living costs during the Master’s degree course. The next application window is open Nov, 1 - Nov, 30 2026, 11.59h, MEZ for a start in the Master programme in HS27.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Same page: ESOP is applied for through eApply (the Master application) and only within the first application window; criteria include ''Very good result in Bachelor''s degree programme (top 10% ... = grade A; self-assessment)'', a Master''s thesis pre-proposal and two professor reference letters; value ''CHF 12''000 per semester, from HS27 onwards 13''500 CHF'' plus a tuition fee waiver, for the regular programme length; ''approximately 60 ESOP scholarships'' for 2027/28, decision end of March. Not eligible if already enrolled in an ETH Master''s or holding a Master''s degree. URGENT: the window closes 30 Nov 2026 (6 days after research date). ''11.59h'' is read as 11:59 (one minute before the noon close in eApply); a student-facing note should tell students to finish before noon CET. [Verifier note: FOUND on 2026-11-24; one later full-file run got a transient ''fetch failed'' for ethz.ch, and an immediate rerun printed FOUND.]"}'::jsonb, '{"value":"Motivation letter of approximately one A4 page in English stating motivation for choosing this specific Master''s programme at ETH Zurich.","source_url":"https://ethz.ch/en/studies/master/application/master-informatik.html","evidence_snippet":"Approximately one A4 page in the language of instruction of the chosen programme, stating your motivation for choosing this specific Master''s degree programme at ETH Zurich.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Language of instruction is English."}'::jsonb, '{"value":2,"source_url":"https://ethz.ch/en/studies/master/application/master-informatik.html","evidence_snippet":"Two recommendation letters in English. We strongly prefer letters from academia, or from referees with an academic background.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Applies to applicants with a non-ETH bachelor''s degree."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"Exempt only if the whole bachelor''s programme was taught completely in English, officially confirmed by the university''s central administration (e.g. Registrar''s Office) with official stamp and signature; letters from teachers or professors are not accepted.","source_url":"https://ethz.ch/en/studies/master/application/language-requirements.html","evidence_snippet":"Applicants who complete a Bachelor’s degree programme completely taught in English. The language of instruction must be officially confirmed by the university. No confirmations are required for Bachelor''s degrees from Australia, Ireland, New Zealand, the United Kingdom and the United States.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Important warning on the same page: ''Confirmations on the language of instruction which do not fulfill the exemption reasons will lead to a direct rejection of the application, since it is not possible to submit a language certificate after the application deadline.'' ETH recommends taking a test if English was not the only language of instruction. Transcripts can serve as the confirmation only if they explicitly name English as the only teaching language of the entire programme."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('wuerzburg-msc-cs', 'uni-wuerzburg', 'MSc Computer Science', 'DE', 'MSc', 'cs', 'https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2027-03-15","source_url":"https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/application/","evidence_snippet":"The application deadline for the winter semester is from the end of January to March 15","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Winter semester 2027/28. Page gives no year; 15 March is the next occurrence (2027). Programme page also shows ''application deadline winter semester: 15.3.'' Summer semester: end of August to 31 October. Non-German bachelor''s holders need a uni-assist VPD issued for Würzburg, so start early.","basis":"inferred","note":"For the winter semester. The application window runs from the end of January to 15 March."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":null,"toefl_ibt":null,"waiver":"Medium of instruction certificate proving the Bachelor''s degree programme was entirely taught in English or German","text":"Either German B2 or English C1 language proficiency"},"source_url":"https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/application/","evidence_snippet":"Either German B2 or English C1 language proficiency (alternative a medium of instruction certificate that proves that your Bachelor''s degree programme was entirely taught in English or German)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. No numeric IELTS/TOEFL score stated; page mentions IELTS only as an example of a C1 certificate."}'::jsonb, '{"value":{"amount":0,"currency":"EUR","period":"semester"},"source_url":"https://www.uni-wuerzburg.de/en/international/studying-in-wuerzburg/degree-programmes/before-arrival/costs-and-financing","evidence_snippet":"There are no tuition fees at the University of Würzburg. But you have to pay the semester contribution each semester for enrolment or re-enrolment.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. University-wide statement on the page for international degree-seeking students (no nationality restriction stated). The semester contribution (student contribution + semester ticket) is still payable each semester; the amount is not on this page (it points to the Unit for Student Affairs).","note":"No tuition fees, but a semester contribution is due each semester. Its amount is not verified yet."}'::jsonb, '{"value":{"amount":1000,"currency":"EUR","period":"month"},"source_url":"https://www.uni-wuerzburg.de/en/international/studying-in-wuerzburg/degree-programmes/before-arrival/costs-and-financing","evidence_snippet":"Of course this also depends strongly on the individual life style, but you should expect monthly costs of about €1000.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Breakdown on the same page: Eating €275, Living €375, Health Insurance €110, Other €222 (plus broadcasting fee). This is a university estimate, not the German student-visa blocked-account amount."}'::jsonb, '{"value":24,"source_url":"https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/","evidence_snippet":"Standard length of programme: 4 semester (120 ECTS)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. 4 semesters = 24 months."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"scale":"german","min":4,"text":"German grade worse than 2.5: may be invited to an oral aptitude test. Required test grade by bachelor grade: 2.6-3.0 needs 4.0 (no test if the degree was finished in the standard length); 3.1-3.5 needs 3.0 (3.5 if standard length); 3.6-4.0 needs 2.0 (2.5 if standard length)."},"source_url":"https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/application/","evidence_snippet":"If your first degree was completed in the standard length of programme you will also receive a grade bonus of 0.5. Grade of Bachelor''s degree Required grade in the aptitude test Required grade if Bachelor''s degree in standard length of programme 2.6 - 3.0 4.0 No aptitude test required 3.1 - 3.5 3.0 3.5 3.6 - 4.0 2.0 2.5","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. German scale, lower is better; min 4.0 = the table covers every passing bachelor grade up to 4.0. Same page: ''If you fulfil these requirements but with a grade worse than 2.5 you can be invited to an oral aptitude test for admittance'' (30-minute oral test on theoretical, practical and technical computer science; may switch to a written exam if many tests are needed). The Pakistani CGPA must first be converted to the German scale (modified Bavarian formula, a conversion rule in code, not on this page). ''Can be invited'' is not a guarantee."}'::jsonb, '{"value":"A medium-of-instruction certificate proving the bachelor''s programme was taught entirely in English (or German) is accepted instead of an English C1 or German B2 certificate.","source_url":"https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/application/","evidence_snippet":"Either German B2 or English C1 language proficiency (alternative a medium of instruction certificate that proves that your Bachelor''s degree programme was entirely taught in English or German)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Same rule already sits in language_req.waiver; proposed here for the new language_waiver field. The required-documents list on the same page repeats it: ''B2 German or C1 English proficiency certificate (e.g. IELTS or a proof of English/German as a medium of instruction in your Bachelor''s degree)''."}'::jsonb, '{"value":"master.informatik@uni-wuerzburg.de","source_url":"https://www.informatik.uni-wuerzburg.de/en/studies/degree-programmes/master-computer-science/application/","evidence_snippet":"Please direct any questions regarding your application or any additional documents after the deadline to master.informatik@uni-wuerzburg.de.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Departmental contact for CS MSc applications."}'::jsonb, '2026-11-24'::date),
  ('imperial-msc-computing', 'imperial', 'MSc Computing', 'UK', 'MSc', 'cs', 'https://www.imperial.ac.uk/study/courses/postgraduate-taught/computing/', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"October 2027","source_url":"https://www.imperial.ac.uk/study/courses/postgraduate-taught/computing/","evidence_snippet":"Duration 1 year Start date October 2027","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Single October entry point. The department page says ''Admissions for September 2027 are now open'' (refers to the admissions cycle; same page says single entry-point in October)."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":7,"toefl_ibt":null,"waiver":null,"text":"Higher university requirement: IELTS Academic 7.0 overall (minimum 6.5 in all elements)"},"source_url":"https://www.imperial.ac.uk/study/apply/english-language/","evidence_snippet":"IELTS – Academic (Test-Centre/UKVI SELT/Online) Standard Higher 6.5 overall (minimum 6.0 in all elements) 7.0 overall (minimum 6.5 in all elements)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Course page states: ''For admission to this course, you must achieve the higher university requirement in the appropriate English language qualification.'' TOEFL iBT moved to a new 1-6 band scale on 21 Jan 2026, so no iBT number proposed.","note":"The course page says: \"For admission to this course, you must achieve the higher university requirement in the appropriate English language qualification.\""}'::jsonb, '{"value":{"amount":48300,"currency":"GBP","period":"year"},"source_url":"https://www.imperial.ac.uk/study/courses/postgraduate-taught/computing/","evidence_snippet":"Overseas fee 2027 entry £48,300","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Overseas fee, 2027 entry, one-year programme (so year = total). Home fee £25,850. Application fee £90."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":12,"source_url":"https://www.imperial.ac.uk/computing/prospective-students/courses/pg/msc-computing/","evidence_snippet":"The programme is full time and is taken over 12 months, with a single entry-point in October.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Department of Computing page. Course page key facts: ''Duration 1 year'', ''Start date October 2027''."}'::jsonb, '{"value":"Imperial Inspires Scholarships (Postgraduate taught, 2027/2028): £15,000 for international students who pay the Overseas tuition rate on a full-time course; Computing is one of the listed departments. If a scholarship is available for your course and you meet the entry and eligibility requirements, Imperial invites you to apply after you submit your course application.","source_url":"https://www.imperial.ac.uk/study/fees-and-funding/scholarships-search/imperial-inspires-scholarships-postgraduate-taught-20272028.php","evidence_snippet":"Imperial Inspires Scholarships (Postgraduate taught) Scholarship overview Degree level Postgraduate taught, Master''s research Value £15,000 Number of awards 200 Academic year 2027/2028 Tuition fee status Overseas Mode of study Full time","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Computing is on the same page directly below the snippet: ''Available to applicants in the following departments Aeronautics Bioengineering Brain Sciences Business School Centre for Environmental Policy Chemical Engineering Chemistry Civil and Environmental Engineering Computing ...'' (the department list made a single snippet longer than 400 characters). Same page: ''An international student who is eligible to pay the Overseas rate of tuition'' and ''Applying for a full-time postgraduate taught course within the Faculty of Engineering ...''; new entrants only; ''If an Imperial Inspires Scholarship is available for your course and you meet the minimum entry and eligibility requirements, you will be invited to apply for the scholarship.'' The page lists Computing as a department, not the MSc Computing course by name; course-level availability is on the ''How to apply for an Imperial Inspires Scholarship'' page. 200 awards. Scholarship deadlines are tied to application rounds and were deliberately NOT copied (the Imperial deadline stays null for the demo refusal). Imperial''s Women in STEM 2027-28 page currently names Brazil only, so it was not proposed."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"For graduates of subjects other than computing: the minimum is a First-Class degree in a subject without substantial computing content.","source_url":"https://www.imperial.ac.uk/study/courses/postgraduate-taught/computing/","evidence_snippet":"A First-Class degree in a subject without substantial computing content, and a good performance in Mathematics at A-level or an equivalent qualification at a minimum.","fetched_at":"2026-11-24","review_note":"Added after review: conversion MSc; BS CS graduates are not the target audience."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"No waiver for a Pakistani degree: Imperial exempts only applicants who completed a qualification equivalent to a UK degree in Australia, Canada, Guyana, Ireland, Malta, New Zealand, South Africa, the United Kingdom, the USA or the West Indies.","source_url":"https://www.imperial.ac.uk/study/apply/english-language/english-language-exemption/","evidence_snippet":"You do not need to prove your knowledge of English as part of your application if you’ve completed a qualification equivalent to a UK degree in one of the following countries: Australia Canada Guyana Ireland Malta New Zealand South Africa United Kingdom United States of America West Indies","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Pakistan is not on the list, and the page names no medium-of-instruction route. Other exemptions on the page are medical-registration only."}'::jsonb, '{"value":"doc-mscadmissions@imperial.ac.uk","source_url":"https://www.imperial.ac.uk/study/courses/postgraduate-taught/computing/","evidence_snippet":"Email: doc-mscadmissions@imperial.ac.uk","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Department of Computing MSc admissions contact on the course page."}'::jsonb, '2026-11-24'::date),
