  ('brookes-msc-cs', 'oxford-brookes', 'MSc Advanced Computer Science', 'UK', 'MSc', 'cs', 'https://www.brookes.ac.uk/courses/postgraduate/advanced-computer-science', 'active', 'direct', '{"value":"Extra compliance measures for Pakistan applicants (January 2027 entry timeline): no offers beyond 23 October 2026, no CAS issuance beyond 11 December 2026, higher pre-CAS interview threshold (7.0 overall).","source_url":"https://www.brookes.ac.uk/study/international-students/applying-to-arriving/how-to-apply","evidence_snippet":"Pakistan No offers beyond 23 October 2026 No CAS issuance beyond 11 December 2026 Higher pre-CAS interview threshold (7.0 overall required with 7.0 in the four core questions)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Published under the January 2027 entry timeline; September 2027 timeline not yet published. Same page: Student visa sponsorship is paused for ''Pakistan (foundation and Pre-Masters only)'' - direct MSc entry is not paused. Applicants from Azad Jammu and Kashmir, Khyber Pakhtunkhwa and Punjab must pay the full first-year tuition fee to release their CAS (£3,000 to accept the offer)."}'::jsonb, '{"value":"January 2027, September 2027","source_url":"https://www.brookes.ac.uk/courses/postgraduate/advanced-computer-science","evidence_snippet":"Starts January 2027, September 2027","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Two intakes."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"scale":"cgpa_4","min":2.7,"text":"2:2 (for direct entry) 60% or GPA 2.7","alternatives":[{"scale":"percent","min":60}]},"source_url":"https://www.brookes.ac.uk/study/international-students/your-country/pakistan/entry-requirements","evidence_snippet":"Bachelor degree requirement Equivalent grading 2:1 (for direct entry) 65% or GP 3.0 2:2 (for direct entry) 60% or GPA 2.7","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Course requires a 2:2 UK bachelor''s in a computer-related subject, so the 2:2 row applies. Page does not state the GPA scale (assumed /4.0). Page shows ''GP 3.0'' (likely typo for GPA). Pass grade for a pre-master''s course: 40% or GPA 1.0. Percent alternative (60%) added from the same snippet on 2026-11-24.","basis":"inferred","note":"The page gives GPA 2.7 without naming the scale. We read it as out of 4.0, the usual Pakistani scale."}'::jsonb, '{"value":{"ielts_overall":6,"toefl_ibt":null,"waiver":null,"text":"IELTS 6.0 overall with 6.0 in all skills"},"source_url":"https://www.brookes.ac.uk/courses/postgraduate/advanced-computer-science","evidence_snippet":"IELTS 6.0 overall with 6.0 in all skills. For more information, please see our English language requirements.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Course-specific requirement. Separately, Brookes applies a higher pre-CAS interview threshold for Pakistan (see status_note)."}'::jsonb, '{"value":{"amount":20800,"currency":"GBP","period":"year"},"source_url":"https://www.brookes.ac.uk/courses/postgraduate/advanced-computer-science","evidence_snippet":"2026/27 2027/28 Home full-time £9,950, £8,950 (PGDip), £4,975 (PGCert) £10,250, £9,250 (PGDip), £5,125 (PGCert) Home part-time £4,975 £5,125 International full-time £19,600 £20,800","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Fee table columns are 2026/27 then 2027/28: £20,800 is the 2027/28 international full-time fee (£19,600 for 2026/27). First year only; September-start MSc is 12 months.","note":"£20,800 is the 2027/28 international fee (2026/27: £19,600). Fees quoted are for the first year only."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":12,"source_url":"https://www.brookes.ac.uk/courses/postgraduate/advanced-computer-science","evidence_snippet":"Full time: MSc - September Start - 1 year (12 months); January Start - 1.5 years (18 months)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. September start = 12 months; January start = 18 months.","note":"September start: 12 months. January start: 18 months."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('qmul-premasters-cs', 'qmul', 'Pre-Master''s (Humanities & Social Sciences) route to MSc Computer Science (Conversion)', 'UK', 'Pre-Master''s + MSc', 'cs', 'https://www.qmul.ac.uk/international-students/pathway-programmes/pmp/humanities-and-social-science/', 'active', 'pre_masters', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"January 2027 and September 2027","source_url":"https://www.qmul.ac.uk/international-students/pathway-programmes/pmp/humanities-and-social-science/","evidence_snippet":"Start dates - January 2027 and September 2027","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. January start: 25/01/2027 to 16/07/2027."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":5.5,"toefl_ibt":null,"waiver":null,"text":"Band 2: IELTS (Academic) 5.5 overall with 5.5 in each of Writing, Listening, Reading and Speaking"},"source_url":"https://www.qmul.ac.uk/international-students/pathway-programmes/pmp/humanities-and-social-science/","evidence_snippet":"Band 2: IELTS (Academic) minimum score of 5.5 overall with 5.5 in each of Writing, Listening, Reading and Speaking","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Entry to the Pre-Masters Graduate Diploma, not to the MSc."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"Queen Mary''s Global Talent Scholarship (Postgraduate Taught, September 2027) does not include Pre-masters programmes (standalone or integrated).","source_url":"https://www.qmul.ac.uk/scholarships/items/global-talent-scholarship--postgraduate-taught-september-2027.html","evidence_snippet":"Pre-masters programmes (standalone and integrated) are not included in the Global Talent Scholarship scheme.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Global Talent Scholarship - Postgraduate Taught (September 2027): £6,000 for international offer holders with at least a 2:1 or overseas equivalent and overseas fee status; ''Pre-masters programmes (standalone and integrated)'' are also in its list of ineligible programmes. The page does not say whether a student who later progresses to the MSc Computer Science (Conversion) can receive it, so this text only covers the Pre-Masters stage. Useful against consultant claims of a scholarship on the Pre-Masters."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"Students must meet specific requirements to progress onto the Master''s; MSc Computer Science (Conversion) is a listed progression degree. Specific progression marks are not published on the page.","source_url":"https://www.qmul.ac.uk/international-students/pathway-programmes/pmp/humanities-and-social-science/","evidence_snippet":"You will need to meet specific requirements to progress onto your Master’s degree programme. Progression degrees MSc Accounting and Management MSc Computer Science (Conversion)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. The numeric progression grade was not found on any official HTML page checked; ask QMUL. Progression is to the CONVERSION MSc (for non-CS graduates), not MSc Advanced Computer Science."}'::jsonb, '{"value":"The Masters this route leads to, MSc Computer Science (Conversion), is for graduates whose degree is not related to Computer Science, Software Engineering, Information Technology or Electronic Engineering.","source_url":"https://www.qmul.ac.uk/postgraduate/taught/coursefinder/courses/computer-science-conversion-msc/","evidence_snippet":"A 2:1 or above at undergraduate level in a degree not related to Computer Science, Software Engineering, Information Technology or Electronic Engineering.","fetched_at":"2026-11-24","review_note":"Added after review: the only CS progression degree from this pre-master''s is the Conversion MSc. Snippet from its entry requirements."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('utoronto-mscac', 'utoronto', 'Master of Science in Applied Computing (MScAC)', 'CA', 'MScAC', 'cs', 'https://mscac.utoronto.ca/', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2026-12-01","source_url":"https://mscac.utoronto.ca/apply/","evidence_snippet":"Fall 2027 applications are now open. The application deadline is December 1, 2026, at 11:59 p.m. ET.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Fall 2027 (September 2027) intake. Single deadline for all applicants (domestic and international); application fee must also be paid by the deadline. Interviews/offers rolling Dec-April.","note":"For Fall 2027. The deadline is 11:59 p.m. Toronto time (ET) on 1 December 2026."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":7,"toefl_ibt":93,"waiver":"Normally exempt if the admitting degree is from an institution recognized by U of T where the language of instruction and examination is uniformly English (MScAC may still require a letter confirming the language of instruction).","text":"U of T School of Graduate Studies minimums: IELTS Academic 7.0 overall with at least 6.5 in each component; TOEFL iBT 93 overall with Writing/Speaking 22 (new 1-6 scale: overall 4.5, Writing 4.5, Speaking 4.0)."},"source_url":"https://www.sgs.utoronto.ca/future-students/admission-application-requirements/english-language-proficiency-testing/","evidence_snippet":"www.ielts.org Minimum required score: 7.0 (Academic) with at least 6.5 for each component.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. SGS-wide minimums (the MScAC apply page defers to SGS ELP requirements). TOEFL figure is from the same SGS page table: ''Overall Score: 93 Writing / Speaking: 22'' (identical for all four SGS divisions); the snippet only covers the IELTS line. Pakistan is not on the SGS exempt-country list; exemption depends on the degree being uniformly English-medium."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":16,"source_url":"https://mscac.utoronto.ca/","evidence_snippet":"Graduate in just 16 months, with the skills, experience and connections to move your career forward.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Includes the eight-month paid research internship."}'::jsonb, '{"value":"MScAC students are not eligible for departmental funding. They are eligible for several provincial and University of Toronto scholarships, listed on the School of Graduate Studies'' Scholarships and Awards page.","source_url":"https://mscac.utoronto.ca/apply/","evidence_snippet":"MScAC students are not eligible for departmental funding. However, MScAC students are eligible for several provincial and University of Toronto scholarships. For a detailed list, please visit the School of Graduate Studies’ Scholarships and Awards page.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. MScAC apply page FAQ (''Which scholarships are available to MScAC students?''). Names no specific scholarship and does not say which ones international students can hold. Same page: ''International students may be eligible to apply for scholarships offered by their home government or loans provided by international student loan companies such as MPower Financing or Prodigy Finance'' (no partnership). It also says internships are usually paid (average $65,000 per eight-month internship in 2026) but ''Remuneration cannot be guaranteed'' - do not present the salary as income."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":3,"source_url":"https://mscac.utoronto.ca/apply/","evidence_snippet":"We require three letters of support from faculty members and/or employers.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Ideally at least two academic references; industry referees in a senior/supervisory capacity are acceptable."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"GRE optional but highly encouraged unless you have (or are about to get) a degree from a Canadian university.","source_url":"https://mscac.utoronto.ca/apply/","evidence_snippet":"Submitting GRE results is optional, although good scores can help strengthen your application. Unless you have (or are about to get) a degree from a Canadian university, then it is highly encouraged to submit your GRE test scores.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Applies to Pakistani applicants (non-Canadian degree): GRE strongly encouraged, not mandatory. If GRE is submitted and an offer made, the offer is conditional on official electronic GRE verification."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"May be exempt if the undergraduate degree was earned at a university where instruction and examination were uniformly in English; a letter from the home university confirming this may still be required.","source_url":"https://mscac.utoronto.ca/apply/","evidence_snippet":"If the undergraduate degree was earned at a university where the language of instruction and examination was uniformly English, an applicant may be exempt. However, a letter confirming the language of instruction and examination may still be required and must be provided by the applicant’s home institution.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Relevant to Pakistani universities that teach and examine fully in English. ''May be exempt'' is discretionary. If a degree was split between two institutions and one was not uniformly English, scores are required. Same page FAQ: an ELP sub-score below the minimum does not automatically rule an applicant out (reviewed case by case)."}'::jsonb, '{"value":"admissions@mscac.utoronto.ca","source_url":"https://mscac.utoronto.ca/contact/","evidence_snippet":"E-mail: admissions@mscac.utoronto.ca","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Listed under ''Prospective Students'' on the MScAC contact page."}'::jsonb, '2026-11-24'::date),
  ('cmu-mscs', 'cmu', 'MS in Computer Science (MSCS)', 'US', 'MS', 'cs', 'https://csd.cmu.edu/academics/masters/overview', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2026-12-09","source_url":"https://csd.cmu.edu/academics/masters/admissions","evidence_snippet":"Early Application Deadline: November 18, 2026 (3 p.m. EST) Final Application Deadline: December 9, 2026 (3 p.m. EST)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Fall 2027 entry (fall only; no spring start). Final deadline used; the early deadline (Nov 18, 2026, $80 fee) has passed, fee after that is $100 per program. Same dates on the SCS graduate admissions page; CMU recommends taking GRE/English tests no later than Nov 25, 2026.","note":"The final deadline is 3 p.m. US Eastern time (EST) on 9 December 2026."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":18,"source_url":"https://csd.cmu.edu/academics/masters/ms-in-computer-science","evidence_snippet":"Most students will complete the program in three semesters, but if you’re switching to computer science from another field, you may need an additional semester to fill gaps in your undergraduate training.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. basis=inferred: three semesters converted at 6 months per semester (the same convention as src/lib/cost.ts and the accepted TUM ''4 semesters = 24 months''). In calendar terms a Fall 2027 start finishing after the third semester is roughly August 2027 - December 2028. ''Most students'': students switching from another field may need a fourth semester (24 months).","note":"Most students finish in three semesters; switching from another field may need one more semester."}'::jsonb, '{"value":"Scholarships and financial assistance are not offered by the MSCS program at this time.","source_url":"https://csd.cmu.edu/academics/masters/admissions","evidence_snippet":"Financial Information Scholarships and financial assistance to the Master of Science Program are not offered by the program at this time.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. CSD master''s admissions page, MSCS section. A separate ''Financial Information'' block on the same page is for the Fifth Year M.S. (not relevant to Pakistani applicants). Useful against consultant scholarship promises for CMU MSCS."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":3,"source_url":"https://csd.cmu.edu/academics/masters/admissions","evidence_snippet":"Three letters of recommendation: At least two letters should be from faculty or recent employers.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. MSCS application requirement."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"GRE strongly recommended, especially if you do not have clear documentation of strong mathematical proficiency.","source_url":"https://csd.cmu.edu/academics/masters/admissions","evidence_snippet":"The GRE is strongly recommended in order to apply to the MSCS program, especially for students who do not have clear documentation of strong mathematical proficiency.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Fall 2027 cycle. GRE at Home only accepted for specific historical score dates."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"No waivers: study at an English-language school, college or university outside the US does not waive the test, and medium-of-instruction (MOI) certificates are not accepted.","source_url":"https://www.cs.cmu.edu/education/graduate-admissions","evidence_snippet":"We also do not issue waivers based on previous study at an English-language high school, college or university outside of the United States. No amount of educational experience in English, regardless of the country it occurred in, will result in a test waiver.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Same page: ''Medium of Instruction (MOI) certificates are not accepted as a substitute for an English proficiency test.'' Also time-sensitive: ''we highly recommend that you take the exam no later than November 25, 2026'' because scores take about two weeks and the deadline is 9 December 2026."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('uiuc-mscs', 'uiuc', 'MS in Computer Science', 'US', 'MS', 'cs', 'https://siebelschool.illinois.edu/academics/graduate/ms-program', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2026-12-01","source_url":"https://siebelschool.illinois.edu/admissions/graduate/application-deadlines","evidence_snippet":"M.S. in Computer Science Fall only December 1 March 15","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Deadline table gives ''December 1'' without a year; next occurrence for Fall 2027 entry is 2026-12-01. March 15 is the decision deadline. Fall entry only. [Verifier note: siebelschool.illinois.edu responds slowly to the verifier user agent (sometimes >15s); snippet printed FOUND on retry on 2026-11-24.]","basis":"inferred","note":"Fall intake only."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":6.5,"toefl_ibt":79,"waiver":null,"text":"Limited status admission minimum: TOEFL iBT 79 (scores dated before 21 Jan 2026) or 4.0 (after 20 Jan 2026), IELTS Academic 6.5. Full status: TOEFL iBT 103 or 5.0, IELTS 7.5."},"source_url":"https://grad.illinois.edu/admissions/international-applicants","evidence_snippet":"Limited Status Admission Minimum Full Status Admission Minimum TOEFL iBT TOEFL iBT Home Edition 4.0 (for scores dated after 1/20/2026) 79 (for scores dated prior to 1/21/2026) 5.0 (for scores dated after 1/20/2026) 103 (for scores dated prior to 1/21/2026) IELTS Academic Exam 6.5 7.5","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Numbers proposed are the LIMITED-status admission minimums (full status: TOEFL 103 / IELTS 7.5). Siebel School requirement