  ('nyit-mscs', 'nyit', 'MS in Computer Science', 'US', 'MS', 'cs', 'https://www.nyit.edu/academics/degrees/computer-science-ms/', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":6,"toefl_ibt":79,"waiver":null,"text":"Minimum for full admission: IELTS 6.0; TOEFL iBT 79 (old scale) or 4.0 (new scale); PTE 53; Duolingo 105."},"source_url":"https://www.nyit.edu/admissions/international/","evidence_snippet":"The following are the minimum scores required for full admission to New York Tech degree programs: IELTS score: 6.0 TOEFL (iBT) score: 4.0 (new); 79 (old) Pearson PTE score: 53 Duolingo English Test score: 105","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. University-wide international minimums. Waiver only for students who live or were educated in listed English-speaking countries (Pakistan not seen in list)."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"New York Tech offers academic scholarships to international students that may cover partial tuition. There is no separate scholarship application: the admissions committee reviews your file for admission and for scholarship eligibility together.","source_url":"https://www.nyit.edu/admissions/international/student-aid/","evidence_snippet":"While international students are not eligible for federal or state aid, New York Tech offers academic scholarships to international students that may cover partial tuition. There is no separate application for scholarships. When you submit your application and supporting documents, the admissions committee will review your file for admission and for scholarship eligibility.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Same page: ''Scholarships are awarded upon admission to New York Tech, not after you arrive'' and ''Graduate applicants must submit a minimum TOEFL score of 79, IELTS score of 6, PTE score of 53, or Duolingo score of 105 to receive scholarships''. NYIT graduate scholarships page names the Graduate Scholar Award: ''up to $4,050 per year or $2,025 per fall or spring semester'', tuition-only, needs a bachelor''s with 3.3 CGPA (https://www.nyit.edu/admissions/costs-and-aid/financial-aid/scholarships-and-grants/graduate/). Value deliberately avoids the word ''automatically'' (used in the international FAQ: ''automatically considered at the time of admission''), because src/lib/consultant/compare.ts treats /automatic(ally)?/ in scholarship_info as an explicit scholarship guarantee."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"GRE scores required if you are a graduate of a foreign university or have a GPA below the program minimum.","source_url":"https://www.nyit.edu/academics/degrees/computer-science-ms/","evidence_snippet":"Official GRE scores if you are a graduate of a foreign university or have a GPA below the minimum (GRE Code: 2561)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Applies to Pakistani applicants (foreign university graduates)."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"scale":"cgpa_4","min":2.5,"text":"Undergraduate GPA between 2.5 and 2.84: at the director''s discretion, you may be given the opportunity to demonstrate qualifications for full matriculation by achieving a GPA of 3.0 or higher in your first four graduate courses."},"source_url":"https://catalog.nyit.edu/engineering/computer_science_ms/","evidence_snippet":"Applicants who do not qualify for full matriculation and have an undergraduate GPA between 2.5 and 2.84 may, at the discretion of the director, be given the opportunity to demonstrate qualifications for full matriculation by achieving a GPA of 3.0 or higher in the first four graduate courses.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Source is the official New York Tech Catalog 2026-2027 (catalog.nyit.edu). Same catalog entry continues: ''such students may be required to take one or more parts of the GRE'' and ''students in this category will not be permitted to continue in the program for more than two semesters unless they have qualified for fully matriculated status''. It also says ''Students of foreign universities with a CGPA of 2.7 (on a 4.0 scale) would automatically be denied a GRE waiver'', so a Pakistani 2.5 applicant should plan on the GRE. The program admission page (https://www.nyit.edu/academics/degrees/computer-science-ms/admission-requirements/) words it as: ''Minimum undergraduate GPA of 2.85 for full matriculation. If you do not satisfy this criterion, you may be admitted at the dean''s discretion.'' Discretionary, not guaranteed. GPA may be judged on a NACES credential evaluation rather than the raw Pakistani CGPA."}'::jsonb, '{"value":"No waiver for a Pakistani education: New York Tech waives the test only for students who live or were educated in its listed countries, and Pakistan is not on the list.","source_url":"https://www.nyit.edu/admissions/international/","evidence_snippet":"New York Tech requires that all international students show English proficiency by providing TOEFL, IELTS, PTE, or Duolingo test scores when they apply. This requirement is waived for students who live or were educated in one of the following countries:","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. The full list on the same page runs ''... Malawi, Marshall Islands, Mauritius, New Zealand, Nigeria, Papua New Guinea, Sierra Leone, Singapore ...'' (alphabetical; Pakistan absent). The list is too long to quote whole within 400 characters. No medium-of-instruction route is mentioned."}'::jsonb, '{"value":"admissions@nyit.edu","source_url":"https://www.nyit.edu/admissions/international/","evidence_snippet":"Have questions? Reach us at admissions@nyit.edu or +1 516.686.7520.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. International admissions page contact."}'::jsonb, '2026-11-24'::date),
  ('usf-mscs', 'usf', 'MS in Computer Science', 'US', 'MS', 'cs', 'https://www.usf.edu/ai-cybersecurity-computing/academics/graduate/mscs.aspx', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2027-06-01","source_url":"https://www.usf.edu/ai-cybersecurity-computing/academics/graduate/prospective-students.aspx","evidence_snippet":"MS and PhD priority deadlines: Fall: January 15 Spring: September 1 Please see the Office of Admission website for the final university deadlines. MS final university deadlines: Fall: June 1","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Final MS deadline for Fall 2027 = 2027-06-01 (no year on page). Priority deadline Fall: January 15 (2027-01-15) for maximum/funding consideration; after priority, space-available basis. Page does not distinguish international applicants; USF''s International Graduate Student Deadlines page looks deadlines up per program via a link/tool not present in the page HTML, so an earlier international-specific deadline could not be verified.","basis":"inferred","note":"This is the final university deadline for Fall. The same page lists a Fall priority deadline of January 15."}'::jsonb, '{"value":{"scale":"cgpa_4","min":3,"text":"“B” average (3.00 on a 4.00 scale) or better in all work attempted while registered as an undergraduate student working toward a bachelor’s degree"},"source_url":"https://www.usf.edu/admissions/international/admission-information/graduate/academic-requirements.aspx","evidence_snippet":"“B” average (3.00 on a 4.00 scale) or better in all work attempted while registered as an undergraduate student working toward a bachelor’s degree","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. USF university-wide international graduate minimum; programs may add requirements."}'::jsonb, '{"value":{"ielts_overall":6.5,"toefl_ibt":79,"waiver":null,"text":"TOEFL iBT 79 or higher (tests before 21 January 2026) or 4.5 or higher (after 21 January 2026); IELTS 6.5 or higher."},"source_url":"https://www.usf.edu/admissions/international/admission-information/graduate/academic-requirements.aspx","evidence_snippet":"Test of English as a Foreign Language (TOEFL iBT) prior to January 21, 2026 79 or higher Test of English as a Foreign Language (TOEFL iBT) after January 21, 2026 4.5 or higher International English Language Testing System (IELTS) 6.5 or higher","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. University-wide international graduate minimums."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":3,"source_url":"https://www.usf.edu/ai-cybersecurity-computing/academics/graduate/prospective-students.aspx","evidence_snippet":"3 Letters of Recommendation (Must be on official letterhead with recommender’s title and contact)","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Part of a complete Bellini College graduate application."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"GRE required (PDF) for MSCS unless undergraduate degree is from an ABET-accredited program or a Carnegie R1 university, or the applicant completed the USF Pathway to Computing (PTC) Graduate Certificate.","source_url":"https://www.usf.edu/ai-cybersecurity-computing/academics/graduate/prospective-students.aspx","evidence_snippet":"A PDF of GRE Scores is required for all MS majors (excluding MSAI), unless the applicant has an undergraduate degree from ABET-accredited degree programs, or from a Carnegie R1 university, or for applicants who have successfully completed USF Pathway to Computing (PTC) Graduate Certificate.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Most Pakistani applicants will need the GRE unless their program is ABET-accredited."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('uccs-mscs', 'uccs', 'MS in Computer Science', 'US', 'MS', 'cs', 'https://eas.uccs.edu/academics/programs/computer-science-ms', 'active', 'direct', '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"2027-03-01","source_url":"https://eas.uccs.edu/academics/programs/computer-science-ms","evidence_snippet":"International students applying for the program should have all application materials into the Admissions Office at UCCS by March 1st for Fall Semester and by October 1st for Spring Semester.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. International-applicant deadline for Fall 2027; no year given, next occurrence = 2027-03-01. The SAME page also has an ''Application Deadlines'' block saying ''Fall Start: April 1st'' / ''Our Fall application deadline is April 1st'' (which only recommends international students apply as early as possible) - see conflicts_noticed. US applicants: April 1.","basis":"inferred","note":"For international applicants starting in the Fall semester (Spring: 1 October)."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"ielts_overall":6.5,"toefl_ibt":80,"waiver":null,"text":"TOEFL 80 or higher, IELTS 6.5 or higher, or Duolingo 115."},"source_url":"https://eas.uccs.edu/academics/programs/computer-science-ms","evidence_snippet":"A TOEFL score of 80 of higher, an ILETS of 6.5 or higher, or a Duolingo exam score of 115 will be required for proof of English Proficiency.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Snippet typos (''of higher'', ''ILETS'') are verbatim from the page. EAS How to Apply page agrees: TOEFL 80 iBT, IELTS 6.5."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":3,"source_url":"https://eas.uccs.edu/future-student-resources/how-to-apply","evidence_snippet":"Letters of Recommendation: Three letters of recommendation are required for all programs.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Stated for both domestic and international College of Engineering & Applied Science graduate applicants."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":"GRE required (all sections), at least 148 quantitative, unless the applicant has a bachelor''s with GPA 3.0+ from an ABET-accredited CS or closely related program within the U.S.","source_url":"https://eas.uccs.edu/academics/programs/computer-science-ms","evidence_snippet":"All sections of the Graduate Record Examination (GRE) are required, with at least 148 on the quantitative portion, unless one of the following conditions is satisfied: The applicant has a bachelor’s degree with a GPA of 3.0 or above from an ABET-accredited Computer Science or a closely related program from within the U.S.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Exemption is US-only, so Pakistani applicants need the GRE. EAS How to Apply page (international section) agrees: GRE required with at least 148 quantitative."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":{"scale":"cgpa_4","min":null,"text":"GPA below 3.0: if admitted at all, expect provisional admission. GPA below 2.75: if admitted, the Graduate School requires provisional admission. No lower floor is stated."},"source_url":"https://eas.uccs.edu/academics/programs/computer-science-ms","evidence_snippet":"Students with an average GPA below 3.0, if admitted at all, should expect to be admitted provisionally. If a student with a GPA below 2.75 is admitted, then the Graduate School requires provisional admission.","fetched_at":"2026-11-24","review_note":"Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Same paragraph also says: ''Students with an average below 3.0 but above 2.75 will be considered on an individual basis'' and ''Students who recently earned an undergraduate degree with a GPA below 3.00 will be required to take the GRE (Graduate Record Examination) before they can be considered for admission. A score of 148 (new grading scale) on the quantitative portion is considered favorable.'' So a 2.5/4 applicant needs the GRE and, if admitted, is admitted provisionally. The page does not say what provisional status requires after enrolment. Not a promise of admission."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '2026-11-24'::date),
  ('ljmu-msc-cs', 'ljmu', 'MSc Computer Science', 'UK', 'MSc', 'cs', null, 'ruled_out', 'direct', '{"value":"Not accepting Pakistan applicants for 2026/27 (verify on the official page).","source_url":null,"evidence_snippet":null,"fetched_at":null,"note":"Reported, not yet verified. Verify before relying on it."}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, '{"value":null,"source_url":null,"evidence_snippet":null,"fetched_at":null}'::jsonb, null)
insert into public.country_facts (id, country, key, value, source_url, evidence_snippet, fetched_at, basis, note, review_note, conflicts) values
  ('ca-citizenship-rule', 'CA', 'citizenship_rule', '{"text":"You must have been physically present in Canada for at least 1,095 days during the 5 years before you apply.","sort_months":36,"clock_note":"Days spent in Canada as a temporary resident (for example as a student or worker) count as half days, up to a maximum of 365 days."}'::jsonb, 'https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/adult-minor/who.html', 'You must have been physically in Canada for at least 1,095 days (3 years) during your 5-year eligibility period.', '2026-11-24'::timestamptz, null, 'The same page says: "Each day as a temporary resident or protected person during your eligibility period counts as 0.5 days of physical presence in Canada. You can use a maximum of 365 days of physical presence as temporary resident or protected person."', 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Adult applicants (grant of citizenship). Value kept identical to the seed: the official wording matches it. SOURCE URL CORRECTED: the seeded URL (.../become-canadian-citizen/eligibility.html) now redirects to this ''Who can apply'' page (canonical URL). The page defines the eligibility period as ''5 years before the date you sign your application'' and says it ''must include at least 730 days as a permanent resident''. The half-day rule is backed by the companion proposal below (same value, same URL).', null),
  ('de-citizenship-rule', 'DE', 'citizenship_rule', '{"text":"At least 5 years of legal residence in Germany before applying for naturalisation.","sort_months":60,"clock_note":"The clock counts years of legal residence in Germany. Check which permits count."}'::jsonb, 'https://www.auswaertiges-amt.de/en/229970-229970', 'As a general rule, non Germans have the right to become naturalised after five years of legal residence in the Federal Republic of Germany, provided they meet certain additional conditions.', '2026-11-24'::timestamptz, null, null, 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Federal Foreign Office (Auswaertiges Amt, a German federal ministry) English page ''Law on Nationality''. Value kept identical to the seed. SOURCE URL CORRECTED: the seeded bundesregierung.de/breg-en/news/modernisation-of-citizenship-law-2059392 now redirects to a login page (cvd.bundesregierung.de/cvd-de/login), and bmi.bund.de English pages sit behind a cookie-check that the verifier cannot pass. The Federal Government''s own German page https://www.bundesregierung.de/breg-de/aktuelles/kabinett-einbuergerung-2350620 confirms: ''Zukünftig gilt für alle Antragstellenden eine Mindestaufenthaltszeit von fünf Jahren''. Other conditions named on the AA page: sufficient German, naturalisation test, clean record, self-support.', null),
  ('de-dual-nationality-destination', 'DE', 'dual_nationality_destination', '{"text":"Germany generally allows dual citizenship since 27 June 2024."}'::jsonb, 'https://www.auswaertiges-amt.de/en/229970-229970', 'As of 27 June 2024, citizens of all countries who are naturalised in Germany are allowed to hold multiple citizenship.', '2026-11-24'::timestamptz, null, null, 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Federal Foreign Office English page ''Law on Nationality''. Value kept identical to the seed. SOURCE URL CORRECTED (seeded bundesregierung.de English URL now redirects to a login page). The page adds: ''Applicants must find out in advance whether the laws of their country of origin also permit multiple citizenship.'' (Pakistan''s side is deliberately left ''Not verified yet'' per product owner.)', null),
  ('de-citizenship-update', 'DE', 'citizenship_update', '{"text":"The 3-year fast-track route to German citizenship ended in October 2025."}'::jsonb, 'https://www.bundesregierung.de/breg-de/aktuelles/kabinett-einbuergerung-2350620', 'Die bisherige Möglichkeit einer sogenannten „Turboeinbürgerung“ nach 3 Jahren entfällt. Das Gesetz ist am 30. Oktober 2025 in Kraft getreten.', '2026-11-24'::timestamptz, null, null, 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Official Federal Government page (German; English value is a direct rendering). Page dated Thursday 30 October 2025, title ''Staatsangehörigkeit frühestens nach fünf Jahren''; it also says ''Eine Einbürgerung ist frühestens nach fünf Jahren möglich.'' Replaces the seed''s news-report basis with an official source; value kept identical to the seed. Supporting official page: Bundestag vote record https://www.bundestag.de/parlament/plenum/abstimmung/abstimmung?id=962 (''Der Bundestag hat am Mittwoch, 8. Oktober 2025, den Gesetzentwurf der Bundesregierung ... verabschiedet''). NOTE: BAMF''s English naturalisation page still describes the 3-year route - see the conflicting proposal below and conflicts_noticed.', null),
  ('uk-post-study-work', 'UK', 'post_study_work', '{"text":"Graduate visa: 2 years if you apply by 31 December 2026; 18 months if you apply from 1 January 2027.","sort_months":18,"clock_note":"The length depends on the date you apply for the Graduate visa."}'::jsonb, 'https://www.gov.uk/graduate-visa', 'A Graduate visa lasts for: 2 years if you apply on or before 31 December 2026 18 months if you apply on or after 1 January 2027', '2026-11-24'::timestamptz, null, null, 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Non-PhD graduates (the page adds ''If you have a PhD or other doctoral qualification, it will last for 3 years.''). Value kept identical to the seed (seed wording ''by''/''from'' = page wording ''on or before''/''on or after''). The page also says ''Your visa will start from the day your application is approved.'' The clock_note''s 2027-intake reasoning is the seed''s own inference, not page text. Ranking uses 18 months because a Masters starting in 2027 ends after 1 January 2027 (app inference, see DECISIONS.md).', null),
  ('uk-pr-route', 'UK', 'pr_route', '{"text":"The government''s response on earned settlement says the starting point for settlement will move to 10 years, with faster and slower paths available.","sort_months":120,"clock_note":"Under Earned Settlement, time spent on temporary routes will not count towards the qualifying residence period for settlement."}'::jsonb, 'https://www.gov.uk/government/consultations/earned-settlement/outcome/a-fairer-pathway-to-settlement-government-response-to-the-consultation', 'As set out in the Immigration White Paper published in May 2025, the starting point for settlement will move to 10 years, with faster and slower paths available depending on four key principles:', '2026-11-24'::timestamptz, null, null, 'Rewritten after review from the gov.uk response page; both the text and the clock_note are verbatim from that page. Student and Graduate are temporary routes.', null),
  ('us-post-study-work', 'US', 'post_study_work', '{"text":"Optional Practical Training (OPT): up to 12 months, plus a 24-month extension for eligible STEM degrees.","sort_months":36,"clock_note":"OPT can be used before completing your studies (pre-completion) and/or after completing them (post-completion)."}'::jsonb, 'https://www.uscis.gov/working-in-the-united-states/students-and-exchange-visitors/optional-practical-training-opt-for-f-1-students', 'Eligible students can apply to receive up to 12 months of OPT employment authorization before completing their academic studies (pre-completion) and/or after completing their academic studies (post-completion).', '2026-11-24'::timestamptz, null, 'The same page says: "If you have earned a degree in certain Science, Technology, Engineering and Mathematics (STEM) fields, you may apply for a 24-month extension of your post-completion OPT employment authorization."', 'Rewritten after review: "up to 12 months" per USCIS. Ranking assumes a STEM degree (computer science).', null),
