  ('uk-proof-of-funds', 'UK', 'proof_of_funds', '{"text":"For a Student visa you must show money for your course fees for 1 academic year (up to 9 months), as shown on your CAS, plus living costs of £1,529 per month for courses in London or £1,171 per month for courses outside London, for up to 9 months.","clock_note":"You must have this money for at least 28 days in a row. The 28-day period must end within 31 days of the date you apply."}'::jsonb, 'https://www.gov.uk/student-visa/money', '£1,529 per month (for up to 9 months) for courses in London £1,171 per month (for up to 9 months) for courses outside London', '2026-11-24'::timestamptz, null, 'The same page says: "You need enough money to pay for your course for 1 academic year (up to 9 months). The amount you need to pay will be on your Confirmation of Acceptance for Studies (CAS)."', 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Companion snippets: "You need enough money to pay for your course for 1 academic year (up to 9 months). The amount you need to pay will be on your Confirmation of Acceptance for Stu" (https://www.gov.uk/student-visa/money) | "You must have this money for at least 28 days in a row. The end date of the 28-day period must be within 31 days of the date you apply for your visa." (https://www.gov.uk/student-visa/money)', null),
  ('de-proof-of-funds', 'DE', 'proof_of_funds', '{"text":"For visa applications from 1 January 2025, the German Embassy in Pakistan presumes €992 a month (€11,904 a year) must be paid into a blocked account (Sperrkonto). It may ask for a blocked amount for up to two years in particular cases.","money":{"amount":11904,"currency":"EUR","period":"year"},"clock_note":"Your signature on the blocked-account documents must be attested by the Embassy in Islamabad, the Consulate General in Karachi or the Honorary Consul in Lahore."}'::jsonb, 'https://pakistan.diplo.de/pk-en/service/1995528-1995528', 'From 1 January 2025 the presumed annual requirement that must be paid into the blocked account when applying for a visa will increase to 992,00 Euros monthly or 11.904,00 Euros yearly. This increased amount applies to all visa applications submitted from 1 January 2025.', '2026-11-24'::timestamptz, null, 'The same page says: "Please note that a scholarship awarded by a Pakistani University is not sufficient, only a scholarship awarded by HEC can be accepted."', 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Companion snippets: "The Embassy and Consulate General reserve the right to request a blocked amount for up to two years in particular cases." (https://pakistan.diplo.de/pk-en/service/1995528-1995528) | "Please note that a scholarship awarded by a Pakistani University is not sufficient, only a scholarship awarded by HEC can be accepted." (https://pakistan.diplo.de/pk-en/service/1995528-1995528) | "Your signature on the documents to open a blocked account has to be attested by the Embassy in Islamabad, the Consulate General in Karachi or the Honorary Consu" (https://pakistan.diplo.de/pk-en/service/1995528-1995528)', null),
  ('ca-proof-of-funds', 'CA', 'proof_of_funds', '{"text":"For a study permit you must prove, without working in Canada, that you can pay tuition, living expenses and travel. If you apply on or after 1 September 2026 to study outside Quebec, the living-expenses amount for a student coming alone is CAN$23,448 for the first year, not including tuition and transport.","money":{"amount":23448,"currency":"CAD","period":"year"},"clock_note":"The amount is for the first year of your program and is updated each year."}'::jsonb, 'https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html', 'If you apply on or after September 1, 2026 All provinces and territories except Quebec Number of family members (including the applicant) Amount required per year (excluding tuition and transportation costs) (in CAN$) 1 $23,448', '2026-11-24'::timestamptz, null, null, 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Companion snippets: "You must prove that you have enough money, without working in Canada, to pay for all the following: tuition fees for the course or program of studies living exp" (https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html) | "This chart tells you how much money you will need to support yourself and your family members in Canada for the first year of your program of studies. These amo" (https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html)', null),
  ('us-proof-of-funds', 'US', 'proof_of_funds', '{"text":"You must have the money to cover tuition, books, living expenses and travel. Your school checks this before it issues your Form I-20, and the I-20 lists the costs and your financial resources."}'::jsonb, 'https://studyinthestates.dhs.gov/students/prepare/financial-ability', 'Prospective F-1 or M-1 students must have the financial resources to live and study in the United States. This includes being able to cover the cost of tuition, books, living expenses and travel. Designated school officials (DSOs) must collect evidence of the student’s financial ability before issuing a Form I-20, “Certificate of Eligibility for Nonimmigrant Student Status.”', '2026-11-24'::timestamptz, null, null, 'Proposed from the official page on 2026-11-24 and checked by a second reviewer. Awaiting human review. Companion snippets: "The Form I-20 includes the following information: Personal and academic details about the student. Student and Exchange Visitor Information System (SEVIS) ID nu" (https://studyinthestates.dhs.gov/2025/07/sevp-form-series-understanding-the-form-i-20)', null),
  ('ch-proof-of-funds', 'CH', 'proof_of_funds', null, null, null, null, null, 'Not verified yet.', null, null)
insert into public.conversion_rules (id, scope, from_scale, to_scale, formula, params, source_url, evidence_snippet, fetched_at, notes) values
  ('pk-cgpa4-to-german-modified-bavarian', 'PK->*', 'cgpa_4', 'german', 'modified_bavarian', '{"nmax":4,"nmin":[1,2]}'::jsonb, null, null, null, 'Modified Bavarian formula: German grade = 1 + 3 x (Nmax - Nd) / (Nmax - Nmin). Nmin (lowest passing CGPA on your transcript) differs between universities, so a range of 1.0 to 2.0 is used until you enter your own. Add the official source URL and snippet before fit decisions use this rule.')
